def check_graph():
    import itertools
    n = 21
    subsets_5 = list(itertools.combinations(range(n), 5))

    for attempt in range(1000):
        edges = []
        adj = {i: set() for i in range(n)}
        for i in range(n):
            for j in range(i+1, n):
                if random.random() < 0.6:
                    edges.append((i, j))
                    adj[i].add(j)
                    adj[j].add(i)

        # Check min degree >= 4
        if any(len(adj[i]) < 4 for i in range(n)):
            continue

        # Check independent set of size 5
        has_ind_5 = False
        for subset in subsets_5:
            is_ind = True
            for i in range(5):
                for j in range(i+1, 5):
                    if subset[j] in adj[subset[i]]:
                        is_ind = False
                        break
                if not is_ind:
                    break
            if is_ind:
                has_ind_5 = True
                break

        if has_ind_5:
            continue

        # Check connectivity >= 4
        # A graph has connectivity >= 4 if removing any 3 vertices leaves it connected
        subsets_3 = list(itertools.combinations(range(n), 3))
        is_conn = True
        for rem in subsets_3:
            rem_set = set(rem)
            start = next(i for i in range(n) if i not in rem_set)
            visited = {start}
            q = [start]
            while q:
                curr = q.pop(0)
                for neighbor in adj[curr]:
                    if neighbor not in rem_set and neighbor not in visited:
                        visited.add(neighbor)
                        q.append(neighbor)
            if len(visited) < n - 3:
                is_conn = False
                break

        if is_conn:
            print("Found!")
            print(edges)
            return edges

    print("Not found")

check_graph()
